import xml.etree.ElementTree as ET
from pathlib import Path

HP = '{http://www.hancom.co.kr/hwpml/2010/HWPML}'

update = {
  'customer_full': 'Asteron Commerce',
  'owner_name': '한예진',
  'window_start': '2026-08-12',
  'window_end': '2026-08-26',
  'band': 'Priority-24M',
  'escalation_email': 'renewals-escalation@asteron.example',
  'note': '가격 검토가 끝날 때까지 할인 문구를 외부에 공유하지 마세요.',
}

followups = [
  (1, '보안 검토 완료 일정을 고객과 다시 확인'),
  (2, '결재 라인에 최신 가격 밴드를 반영'),
  (3, '갱신 주간에 에스컬레이션 연락처를 온콜로 고정'),
]

work = Path('/tmp/hwpx_work_clean/hwpx_contents/Contents')
sec0_path = work/'section0.xml'
sec1_path = work/'section1.xml'

# --- section0 ---
t0 = ET.parse(sec0_path)
r0 = t0.getroot()

# Replace customer in p id=1 runs (two hp:t nodes)
# Find p with id='1'
for p in r0.findall(f'.//{HP}p'):
    if p.get('id') == '1':
        ts = p.findall(f'.//{HP}t')
        if len(ts) >= 2:
            ts[0].text = '고객사: Asteron '
            ts[1].text = 'Commerce'
        elif len(ts) == 1:
            # fallback: write whole string
            ts[0].text = f'고객사: {update["customer_full"]}'
        # remove linesegarray in this paragraph
        for ls in list(p.findall(f'{HP}linesegarray')):
            p.remove(ls)

    if p.get('id') == '2':
        t = p.find(f'.//{HP}t')
        if t is not None and t.text is not None:
            t.text = f'현 담당자: {update["owner_name"]}'
        for ls in list(p.findall(f'{HP}linesegarray')):
            p.remove(ls)

    if p.get('id') == '3':
        t = p.find(f'.//{HP}t')
        if t is not None:
            t.text = f'갱신 윈도우: {update["window_start"]} ~ {update["window_end"]}'
        for ls in list(p.findall(f'{HP}linesegarray')):
            p.remove(ls)

    if p.get('id') == '4':
        t = p.find(f'.//{HP}t')
        if t is not None:
            t.text = f'가격 메모: {update["note"]}'
        for ls in list(p.findall(f'{HP}linesegarray')):
            p.remove(ls)

# Update table cells: p id 31 (band), p id 33 (email)
for p in r0.findall(f'.//{HP}p'):
    if p.get('id') == '31':
        t = p.find(f'.//{HP}t')
        if t is not None:
            t.text = update['band']
        for ls in list(p.findall(f'{HP}linesegarray')):
            p.remove(ls)
    if p.get('id') == '33':
        t = p.find(f'.//{HP}t')
        if t is not None:
            t.text = update['escalation_email']
        for ls in list(p.findall(f'{HP}linesegarray')):
            p.remove(ls)

# write without xml declaration duplication
ET.indent(t0, space='  ', level=0)
t0.write(sec0_path, encoding='UTF-8', xml_declaration=True)

# --- section1 ---
t1 = ET.parse(sec1_path)
r1 = t1.getroot()

# Identify old follow-up paragraphs by exact text
old_texts = ['1. old follow-up alpha', '2. old follow-up beta', '3. old follow-up gamma']

# We'll remove those paragraphs and insert new ones at the first old paragraph position.
# Because ET doesn't provide parent pointers, iterate children of root (direct <hp:p> elements)
children = list(r1)
remove_indices = []
for i, child in enumerate(children):
    if child.tag == f'{HP}p':
        t = child.find(f'.//{HP}t')
        if t is not None and (t.text in old_texts):
            remove_indices.append(i)

if remove_indices:
    insert_at = remove_indices[0]
    # remove from highest index to lowest
    for i in reversed(remove_indices):
        r1.remove(children[i])

    # create new paragraphs modeled after original structure: <hp:p ...><hp:run ...><hp:t>...</hp:t></hp:run></hp:p>
    # Use ids 41,42,43 to mirror originals
    new_ps = []
    for (seq, text), pid in zip(followups, ['41','42','43']):
        p = ET.Element(f'{HP}p', {'id': pid, 'paraPrIDRef': '0'})
        run = ET.SubElement(p, f'{HP}run', {'charPrIDRef': '0'})
        t = ET.SubElement(run, f'{HP}t')
        t.text = text
        new_ps.append(p)

    # insert in order
    for offset, p in enumerate(new_ps):
        r1.insert(insert_at + offset, p)

# Update renewal window confirm paragraph id=44
for p in r1.findall(f'.//{HP}p'):
    if p.get('id') == '44':
        t = p.find(f'.//{HP}t')
        if t is not None:
            t.text = f'갱신 윈도우 확인: {update["window_start"]} ~ {update["window_end"]}'
        # remove linesegarray ONLY here (edited)
        for ls in list(p.findall(f'{HP}linesegarray')):
            p.remove(ls)

# Important: do NOT touch appendix paragraph id=46 (no cache removal)

# Remove linesegarray from newly inserted follow-up paragraphs (edited)
for pid in ['41','42','43']:
    for p in r1.findall(f'.//{HP}p'):
        if p.get('id') == pid:
            for ls in list(p.findall(f'{HP}linesegarray')):
                p.remove(ls)

ET.indent(t1, space='  ', level=0)
t1.write(sec1_path, encoding='UTF-8', xml_declaration=True)

print('updated XML via ET')
